<?php
require_once dirname(__DIR__) . '/core/Controller.php'; require_once dirname(__DIR__) . '/models/Requisition.php';
class RequisitionController extends Controller { private Requisition $model; public function __construct(){ $this->model=new Requisition(); } public function index():void{$this->requireLogin();$this->view('requisitions/index',['title'=>'Requisitions','requisitions'=>$this->model->all()]);} public function create():void{$this->requireLogin();if($_SERVER['REQUEST_METHOD']==='POST'&&$this->validateCsrf()){ $requesterId = (int)($_SESSION['user']['id'] ?? 0); $this->model->create($_POST+['requested_by'=>$requesterId]); $department = trim((string)($_POST['department'] ?? 'General')); $amount = (float)($_POST['total_amount'] ?? 0); notifyTeam(['Administrator','Procurement Officer','Store Officer'], 'New requisition', 'A requisition for ' . $department . ' worth $' . number_format($amount, 2) . ' was submitted.'); } $this->redirect('/index.php?controller=requisition');} public function decide():void{$this->requireModuleAccess('requisition', ['Administrator','Procurement Officer','Store Officer']);if($_SERVER['REQUEST_METHOD']==='POST'&&$this->validateCsrf()){ $id = $this->sanitizeInt($_POST['id'] ?? 0); $status = $this->sanitize($_POST['status'] ?? 'pending'); $approverId = (int)($_SESSION['user']['id'] ?? 0); $comments = $this->sanitize($_POST['comments'] ?? ''); $requisition = $this->model->find($id); $this->model->updateStatus($id, $status, $approverId, $comments); if ($requisition && (int)($requisition['requested_by'] ?? 0) > 0) { createNotification((int)($requisition['requested_by'] ?? 0), 'Requisition update', 'Your requisition #' . $id . ' was marked as ' . $status . '.'); } }$this->redirect('/index.php?controller=requisition');} }
